import { path } from '@servicenow/sdk-build-core'
import { createTestContext, findInput, loadTestFile, unzipInputArray } from '../test-utils'
import { XMLParser } from 'fast-xml-parser'

describe('monthly-incident-report-flow: Round-Trip Test', () => {
    const ctx = createTestContext({ rootDir: path.resolve(__dirname, '../project') })
    beforeAll(() => ctx.initialize())
    afterEach(() => ctx.cleanup())
    /**
     * Round-Trip Test: monthly-incident-report-flow
     *
     * XML Source: sys_hub_flow_de7f449532604daea9e618b15ded457d.xml
     * Fluent Source: monthly-incident-report-flow.now.ts
     *
     * Flow Name: Monthly Incident Report Flow
     * Description: Generates monthly summary reports for all resolved incidents from the previous month
     *
     * This test validates:
     * - XML → Fluent transformation generates correct TypeScript code
     * - Fluent → XML transformation preserves all flow data
     * - Round-trip maintains data integrity
     *
     * Flow Structure:
     * - Trigger: Scheduled monthly (1st of month at 8:00 AM)
     * - Actions: log (3x), lookUpRecords, createRecord, sendNotification
     * - DataPills: trigger.run_start_date_time, resolvedIncidents.Count, reportRecord.record
     *
     * Features: Scheduled monthly trigger, lookUpRecords with date conditions, createRecord with TemplateValue, sendNotification
     */
    test('monthly-incident-report-flow: Round-trip transformation', async () => {
        const xmlFileName = 'sys_hub_flow_de7f449532604daea9e618b15ded457d.xml'
        const project = ctx.createProject()

        // ============================================================================
        // Step 1: XML → Fluent Transformation
        // ============================================================================
        const xmlContent = loadTestFile(xmlFileName, 'example-unit-tests/xml')
        const { changedFiles } = await project.transform({
            path: xmlFileName,
            content: xmlContent,
        })

        expect(changedFiles).toHaveLength(1)
        const fluentContent = changedFiles[0].getContent()
        const fluentFileName = changedFiles[0].getName()

        // Validate imports
        expect(fluentContent).toContain('import {')
        expect(fluentContent).toContain('Flow')
        expect(fluentContent).toContain('action')
        expect(fluentContent).toContain('wfa')
        expect(fluentContent).toContain('trigger')

        // Validate flow definition
        expect(fluentContent).toContain('Flow(')
        expect(fluentContent).toContain("name: 'Monthly Incident Report Flow'")
        expect(fluentContent).toContain(
            "description: 'Generates monthly summary reports for all resolved incidents from the previous month'"
        )

        // Validate trigger - scheduled monthly
        expect(fluentContent).toContain('wfa.trigger(')
        expect(fluentContent).toContain('trigger.scheduled.monthly')
        expect(fluentContent).toContain('day_of_month: 1')
        expect(fluentContent).toContain('time: Time(')

        // Validate Action 1: log - report generation start
        expect(fluentContent).toContain('wfa.action(')
        expect(fluentContent).toContain('action.core.log')
        expect(fluentContent).toContain("annotation: 'Log report generation start'")
        expect(fluentContent).toContain("log_level: 'info'")
        expect(fluentContent).toContain('log_message: `Starting monthly incident report generation at')
        expect(fluentContent).toContain('wfa.dataPill(_params.trigger.run_start_date_time')
        expect(fluentContent).toContain("'glide_date_time'")

        // Validate Action 2: lookUpRecords - resolved incidents
        expect(fluentContent).toContain('action.core.lookUpRecords')
        expect(fluentContent).toContain("annotation: 'Retrieve all resolved incidents from previous month'")
        expect(fluentContent).toContain("table: 'incident'")
        expect(fluentContent).toContain('conditions:')
        expect(fluentContent).toContain('state=6')
        expect(fluentContent).toContain('resolved_atRELATIVEGE@month@ago@1')
        expect(fluentContent).toContain('resolved_atRELATIVELT@month@ago@0')
        expect(fluentContent).toContain('max_results: 1000')
        expect(fluentContent).toContain("sort_column: 'resolved_at'")
        expect(fluentContent).toContain("sort_type: 'sort_desc'")

        // Validate Action 3: log - incident count
        expect(fluentContent).toContain("annotation: 'Log number of resolved incidents found'")
        expect(fluentContent).toContain("log_level: 'info'")
        expect(fluentContent).toContain('log_message: `Found')
        // Validate exact datapill format with actionInstance_2.Count
        expect(fluentContent).toContain('wfa.dataPill(actionInstance_2.Count')
        expect(fluentContent).toContain("'integer'")
        expect(fluentContent).toContain('resolved incidents from previous month')

        // Validate Action 4: createRecord - report record
        expect(fluentContent).toContain('action.core.createRecord')
        expect(fluentContent).toContain("annotation: 'Create monthly incident summary report record'")
        expect(fluentContent).toContain("table_name: 'task'")
        expect(fluentContent).toContain('values: TemplateValue(')
        // Validate short_description
        expect(fluentContent).toContain('short_description:')
        expect(fluentContent).toContain('Monthly Incident Report - Resolved Incidents')
        // Validate description with datapills
        expect(fluentContent).toContain('description:')
        expect(fluentContent).toContain('Monthly incident summary report for previous month')
        expect(fluentContent).toContain('Total resolved incidents:')
        // Validate exact datapill format with actionInstance_2.Count
        expect(fluentContent).toContain('wfa.dataPill(actionInstance_2.Count')
        expect(fluentContent).toContain("'integer'")
        expect(fluentContent).toContain('Generated at:')
        // Validate exact datapill format with _params.trigger.run_start_date_time
        expect(fluentContent).toContain('wfa.dataPill(_params.trigger.run_start_date_time')
        expect(fluentContent).toContain("'glide_date_time'")
        // Validate state and priority with exact values
        expect(fluentContent).toContain("state: '1'")
        expect(fluentContent).toContain("priority: '4'")

        // Validate Action 5: log - report created
        expect(fluentContent).toContain("annotation: 'Log successful report record creation'")
        expect(fluentContent).toContain("log_level: 'info'")
        expect(fluentContent).toContain('log_message: `Monthly incident report successfully created:')
        // Validate exact datapill format with actionInstance_4.record
        expect(fluentContent).toContain('wfa.dataPill(actionInstance_4.record')
        expect(fluentContent).toContain("'reference'")
        expect(fluentContent).toContain('with')
        // Validate exact datapill format with actionInstance_2.Count
        expect(fluentContent).toContain('wfa.dataPill(actionInstance_2.Count')
        expect(fluentContent).toContain("'integer'")
        expect(fluentContent).toContain('resolved incidents')

        // Validate Action 6: sendNotification
        expect(fluentContent).toContain('action.core.sendNotification')
        expect(fluentContent).toContain("annotation: 'Send notification about monthly report generation'")
        // Validate exact datapill format with actionInstance_4.record
        expect(fluentContent).toContain('record: wfa.dataPill(actionInstance_4.record')
        expect(fluentContent).toContain("'reference'")
        expect(fluentContent).toContain("notification: 'monthly_incident_report_notification'")

        // ============================================================================
        // Step 2: Fluent → XML Transformation
        // ============================================================================
        const tempProject = ctx.createProject()
        tempProject.addFile({ path: fluentFileName, content: fluentContent })

        const output = await tempProject.getFile(fluentFileName)!.getOutput()
        expect(output.length).toBeGreaterThan(0)

        // ============================================================================
        // Step 3: Parse and Validate Regenerated XML
        // ============================================================================
        const parser = new XMLParser({ ignoreAttributes: false })
        const mergedRecords: Record<string, any[]> = {}

        for (const file of output) {
            const parsed = parser.parse(file.content)['record_update']
            Object.entries(parsed).forEach(([table, value]) => {
                if (!mergedRecords[table]) {
                    mergedRecords[table] = []
                }
                if (Array.isArray(value)) {
                    mergedRecords[table].push(...value)
                } else if (value && typeof value === 'object') {
                    mergedRecords[table].push(value)
                }
            })
        }

        expect(mergedRecords['sys_hub_flow']).toBeDefined()
        expect(mergedRecords['sys_hub_action_instance_v2']).toBeDefined()

        // Validate flow record
        const flows = mergedRecords['sys_hub_flow']
        const flow = flows.find((f: any) => f.name === 'Monthly Incident Report Flow')
        expect(flow).toBeDefined()
        expect(flow.type).toBe('flow')
        expect(flow.generation_source).toBe('fluent')

        // Validate trigger
        if (mergedRecords['sys_hub_trigger_instance_v2']) {
            const triggerInstances = mergedRecords['sys_hub_trigger_instance_v2']
            const trigger = triggerInstances.find((t: any) => t.flow === flow.sys_id)
            if (trigger) {
                expect(trigger.trigger_type).toBe('monthly')
                const triggerInputs = unzipInputArray(trigger.trigger_inputs)
                const triggerVar = (name: string) => findInput(triggerInputs, name)?.value
                expect(triggerVar('day_of_month')).toBe(1)
                // Note: Time values are stored in UTC in XML and may differ from source
                // Just verify trigger_inputs were decompressed successfully
                expect(triggerInputs).toBeDefined()
            }
        }

        // Validate Actions
        const actionInstances = mergedRecords['sys_hub_action_instance_v2']
        const flowActions = actionInstances.filter((a: any) => a.flow === flow.sys_id)
        expect(flowActions.length).toBe(6)

        // Action 1: log - report generation start
        const logStart = flowActions.find((a: any) => a.comment?.includes('Log report generation start'))
        expect(logStart).toBeDefined()
        expect(logStart.action_type).toBeDefined()
        const logStartValues = unzipInputArray(logStart.values)
        const logStartVar = (name: string) => findInput(logStartValues, name)?.value
        expect(logStartVar('log_level')).toBe('info')
        const logStartMsg = logStartVar('log_message')
        expect(logStartMsg).toContain('Starting monthly incident report generation at')
        expect(logStartMsg).toMatch(/\{\{.*\.run_start_date_time\}\}/)

        // Action 2: lookUpRecords - resolved incidents
        const lookupIncidents = flowActions.find((a: any) =>
            a.comment?.includes('Retrieve all resolved incidents from previous month')
        )
        expect(lookupIncidents).toBeDefined()
        expect(lookupIncidents.action_type).toBeDefined()
        const lookupValues = unzipInputArray(lookupIncidents.values)
        const lookupVar = (name: string) => findInput(lookupValues, name)?.value
        expect(lookupVar('table')).toBe('incident')
        const conditions = lookupVar('conditions')
        expect(conditions).toContain('state=6')
        expect(conditions).toContain('resolved_atRELATIVEGE@month@ago@1')
        expect(conditions).toContain('resolved_atRELATIVELT@month@ago@0')
        expect(lookupVar('max_results')).toBe(1000)
        expect(lookupVar('sort_column')).toBe('resolved_at')
        expect(lookupVar('sort_type')).toBe('sort_desc')

        // Action 3: log - incident count
        const logCount = flowActions.find((a: any) => a.comment?.includes('Log number of resolved incidents found'))
        expect(logCount).toBeDefined()
        expect(logCount.action_type).toBeDefined()
        const logCountValues = unzipInputArray(logCount.values)
        const logCountVar = (name: string) => findInput(logCountValues, name)?.value
        expect(logCountVar('log_level')).toBe('info')
        const logCountMsg = logCountVar('log_message')
        expect(logCountMsg).toContain('Found')
        expect(logCountMsg).toContain('resolved incidents from previous month')
        // Validate datapill reference to lookUpRecords.Count
        expect(logCountMsg).toMatch(/\{\{.*\.Count\}\}/)

        // Action 4: createRecord - report record
        const createReport = flowActions.find((a: any) =>
            a.comment?.includes('Create monthly incident summary report record')
        )
        expect(createReport).toBeDefined()
        expect(createReport.action_type).toBeDefined()
        const createValues = unzipInputArray(createReport.values)
        const createVar = (name: string) => findInput(createValues, name)?.value
        expect(createVar('table_name')).toBe('task')
        const reportValues = createVar('values')
        expect(reportValues).toBeDefined()
        // Validate short_description
        expect(reportValues).toContain('short_description')
        expect(reportValues).toContain('Monthly Incident Report - Resolved Incidents')
        // Validate description with datapills
        expect(reportValues).toContain('description')
        expect(reportValues).toContain('Monthly incident summary report for previous month')
        expect(reportValues).toContain('Total resolved incidents')
        expect(reportValues).toMatch(/\{\{.*\.Count\}\}/)
        expect(reportValues).toContain('Generated at')
        expect(reportValues).toMatch(/\{\{.*\.run_start_date_time\}\}/)
        // Validate state and priority
        expect(reportValues).toContain('state=1')
        expect(reportValues).toContain('priority=4')

        // Action 5: log - report created
        const logCreated = flowActions.find((a: any) => a.comment?.includes('Log successful report record creation'))
        expect(logCreated).toBeDefined()
        expect(logCreated.action_type).toBeDefined()
        const logCreatedValues = unzipInputArray(logCreated.values)
        const logCreatedVar = (name: string) => findInput(logCreatedValues, name)?.value
        expect(logCreatedVar('log_level')).toBe('info')
        const logCreatedMsg = logCreatedVar('log_message')
        expect(logCreatedMsg).toContain('Monthly incident report successfully created')
        // Validate datapill references to createRecord.record and lookUpRecords.Count
        expect(logCreatedMsg).toMatch(/\{\{.*\.record\}\}/)
        expect(logCreatedMsg).toContain('with')
        expect(logCreatedMsg).toMatch(/\{\{.*\.Count\}\}/)
        expect(logCreatedMsg).toContain('resolved incidents')

        // Action 6: sendNotification
        const sendNotif = flowActions.find((a: any) =>
            a.comment?.includes('Send notification about monthly report generation')
        )
        expect(sendNotif).toBeDefined()
        expect(sendNotif.action_type).toBeDefined()
        const notifValues = unzipInputArray(sendNotif.values)
        const notifVar = (name: string) => findInput(notifValues, name)?.value
        // Validate record field contains datapill reference to createRecord.record
        const notifRecord = notifVar('record')
        expect(notifRecord).toBeDefined()
        expect(notifRecord).toMatch(/\{\{.*\.record\}\}/)
        // Validate notification name
        expect(notifVar('notification')).toBe('monthly_incident_report_notification')
    })
})
